def normalize_tags(tags):
    iterator = iter(tags)
    try:
        first = next(iterator)
    except StopIteration:
        return None

    result = [first]
    seen = {first.casefold()}

    for tag in iterator:
        key = tag.casefold()
        if key not in seen:
            seen.add(key)
            result.append(tag)

    return tuple(result)

def most_common_word(words):
    counts = {}
    first_seen = {}

    for word in words:
        normalized = word.casefold()
        if normalized not in counts:
            counts[normalized] = 0
            first_seen[normalized] = word
        counts[normalized] += 1

    if not counts:
        return None

    most_common = max(counts, key=counts.get)
    return first_seen[most_common]

def intersection_labels(first, second):
    if not first or not second:
        return None
    second_labels = set(second)
    seen = set()
    return tuple(
        label
        for label in first
        if label in second_labels and not (label in seen or seen.add(label))
    )

def common_suffix(words):
    iterator = iter(words)
    try:
        first = next(iterator)
    except StopIteration:
        return None

    suffix_length = len(first)
    for word in iterator:
        matched = 0
        limit = min(suffix_length, len(word))
        while matched < limit and first[-matched - 1].casefold() == word[-matched - 1].casefold():
            matched += 1
        suffix_length = matched
        if suffix_length == 0:
            break

    return first[-suffix_length:] if suffix_length else ""

def parse_clock(text):
    import re

    match = re.fullmatch(r"(1[0-2]|[1-9]):([0-5]\d) (AM|PM)", text)
    if match is None:
        raise ValueError("invalid clock value")

    hour = int(match.group(1))
    minute = int(match.group(2))
    marker = match.group(3)

    if marker == "AM":
        hour %= 12
    else:
        hour = hour % 12 + 12

    return hour * 60 + minute

def sort_events(events):
    if not events:
        return None

    from datetime import datetime

    return tuple(sorted(events, key=lambda event: datetime.fromisoformat(event["time"])))

def matrix_multiply(left, right):
    if not left or not right:
        return None

    left_cols = len(left[0])
    if any(len(row) != left_cols for row in left):
        raise ValueError("left matrix must be rectangular")

    right_cols = len(right[0])
    if any(len(row) != right_cols for row in right):
        raise ValueError("right matrix must be rectangular")

    if left_cols != len(right):
        raise ValueError("left columns must match right rows")

    return [
        [
            sum(left[i][k] * right[k][j] for k in range(left_cols))
            for j in range(right_cols)
        ]
        for i in range(len(left))
    ]

def count_islands(grid):
    if len(grid) == 0:
        return None

    columns = len(grid[0])
    if any(len(row) != columns for row in grid):
        raise ValueError("grid must be rectangular")

    rows = len(grid)
    visited = [[False] * columns for _ in range(rows)]
    islands = 0

    for row in range(rows):
        for column in range(columns):
            if grid[row][column] != 1 or visited[row][column]:
                continue

            islands += 1
            stack = [(row, column)]
            visited[row][column] = True

            while stack:
                current_row, current_column = stack.pop()
                for next_row, next_column in (
                    (current_row - 1, current_column),
                    (current_row + 1, current_column),
                    (current_row, current_column - 1),
                    (current_row, current_column + 1),
                ):
                    if (
                        0 <= next_row < rows
                        and 0 <= next_column < columns
                        and not visited[next_row][next_column]
                        and grid[next_row][next_column] == 1
                    ):
                        visited[next_row][next_column] = True
                        stack.append((next_row, next_column))

    return islands
